pub fn load_config() -> Config {
    let file_config = std::fs::read_to_string("config.json")
        .ok()
        .map(|contents| parse_json_config(&contents))
        .unwrap_or_default();

    Config {
        host: std::env::var("HOST")
            .ok()
            .or(file_config.host)
            .unwrap_or_else(|| "127.0.0.1".into()),
        port: std::env::var("PORT")
            .ok()
            .and_then(|value| value.parse().ok())
            .or(file_config.port)
            .unwrap_or(8080),
    }
}

#[derive(Default)]
struct PartialConfig {
    host: Option<String>,
    port: Option<u16>,
}

fn parse_json_config(contents: &str) -> PartialConfig {
    let mut config = PartialConfig::default();

    for entry in contents.trim_matches(|character| character == '{' || character == '}').split(',') {
        let Some((key, value)) = entry.split_once(':') else {
            continue;
        };

        let key = key.trim().trim_matches('"');
        let value = value.trim();
        match key {
            "host" => config.host = Some(value.trim_matches('"').to_owned()),
            "port" => config.port = value.parse().ok(),
            _ => {}
        }
    }

    config
}

